import{_ as a,a0 as l,w as u,s as d,ao as p,I as i,x as s,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何更改 Linux 控制台字體類型和大小 | LCTT x X-CMD","titleTemplate":false,"description":"如何更改 Linux 控制台字體類型和大小 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何更改 Linux 控制台字體類型和大小 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何更改 Linux 控制台字體類型和大小 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190815 How To Change Linux Console Font Type And Size","title":"如何更改 Linux 控制台字體類型和大小","tag":"201908","desc":""},"relativePath":"201908/20190815 How To Change Linux Console Font Type And Size.md","filePath":"[post].md"}'),r={name:"201908/20190815 How To Change Linux Console Font Type And Size.md"};function g(h,n,x,m,c,f){const t=l("Link");return u(),d("div",null,[n[23]||(n[23]=p('<h1 id="如何更改-linux-控制台字體類型和大小" tabindex="-1">如何更改 Linux 控制台字體類型和大小 <a class="header-anchor" href="#如何更改-linux-控制台字體類型和大小" aria-label="Permalink to “如何更改 Linux 控制台字體類型和大小”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201908/23/041741x6qiajjijupjyjsp.jpg" alt=""></p><p>如果你有圖形桌面環境，那麼就很容易更改文本的字體以及大小。但你如何在沒有圖形環境的 Ubuntu 無頭服務器中做到？別擔心！本指南介紹瞭如何更改 Linux 控制台的字體和大小。這對於那些不喜歡默認字體類型/大小或者喜歡不同字體的人來説非常有用。</p><h3 id="更改-linux-控制台字體類型和大小" tabindex="-1">更改 Linux 控制台字體類型和大小 <a class="header-anchor" href="#更改-linux-控制台字體類型和大小" aria-label="Permalink to “更改 Linux 控制台字體類型和大小”">​</a></h3><p>如果你還不知道，這就是無頭 Ubuntu Linux 服務器控制台的樣子。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Ubuntu-Linux-console.png" alt=""></p><p><em>Ubuntu Linux 控制台</em></p>',7)),i("p",null,[n[1]||(n[1]=s("據我所知，我們可以",-1)),e(t,{href:"https://www.ostechnix.com/find-installed-fonts-commandline-linux/"},{default:o(()=>[...n[0]||(n[0]=[s("列出已安裝的字體",-1)])]),_:1}),n[2]||(n[2]=s("，但是沒有辦法可以像在 Linux 桌面終端仿真器中那樣更改 Linux 控制台字體類型或大小。",-1))]),n[24]||(n[24]=p(`<p>但這並不意味着我們無法改變它。我們仍然可以更改控制台字體。</p><p>如果你正在使用 Debian、Ubuntu 和其他基於 DEB 的系統，你可以使用 <code>console-setup</code> 配置文件來設置 <code>setupcon</code>，它用於配置控制台的字體和鍵盤佈局。該控制台設置的配置文件位於 <code>/etc/default/console-setup</code>。</p><p>現在，運行以下命令來設置 Linux 控制台的字體。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dpkg-reconfigure console-setup</span></span></code></pre></div><p>選擇要在 Linux 控制台上使用的編碼。只需保留默認值，選擇 “OK” 並按回車繼續。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Choose-encoding-to-set-on-the-console.png" alt=""></p><p><em>選擇要在 Ubuntu 控制台上設置的編碼</em></p><p>接下來，在列表中選擇受支持的字符集。默認情況下，它是最後一個選項，即在我的系統中 <strong>Guess optimal character set</strong>（猜測最佳字符集）。只需保留默認值，然後按回車鍵。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Choose-character-set-in-Ubuntu.png" alt=""></p><p><em>在 Ubuntu 中選擇字符集</em></p><p>接下來選擇控制台的字體，然後按回車鍵。我這裏選擇 “TerminusBold”。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Choose-font-for-Linux-console.png" alt=""></p><p><em>選擇 Linux 控制台的字體</em></p><p>這裏，我們為 Linux 控制台選擇所需的字體大小。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Choose-font-size-for-Linux-console.png" alt=""></p><p><em>選擇 Linux 控制台的字體大小</em></p><p>幾秒鐘後，所選的字體及大小將應用於你的 Linux 控制台。</p><p>這是在更改字體類型和大小之前，我的 Ubuntu 18.04 LTS 服務器中控制台字體的樣子。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Linux-console-tty-ubuntu-1.png" alt=""></p><p>這是更改之後。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Ubuntu-Linux-TTY-console.png" alt=""></p><p>如你所見，文本更大、更好，字體類型也不同於默認。</p><p>你也可以直接編輯 <code>/etc/default/console-setup</code>，並根據需要設置字體類型和大小。根據以下示例，我的 Linux 控制台字體類型為 “Terminus Bold”，字體大小為 32。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ACTIVE_CONSOLES=&quot;/dev/tty[1-6]&quot;</span></span>
<span class="line"><span>CHARMAP=&quot;UTF-8&quot;</span></span>
<span class="line"><span>CODESET=&quot;guess&quot;</span></span>
<span class="line"><span>FONTFACE=&quot;TerminusBold&quot;</span></span>
<span class="line"><span>FONTSIZE=&quot;16x32&quot;</span></span></code></pre></div><h3 id="附錄-顯示控制台字體" tabindex="-1">附錄：顯示控制台字體 <a class="header-anchor" href="#附錄-顯示控制台字體" aria-label="Permalink to “附錄：顯示控制台字體”">​</a></h3><p>要顯示你的控制台字體，只需輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ showconsolefont</span></span></code></pre></div><p>此命令將顯示字體的字形或字母表。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/show-console-fonts.png" alt=""></p><p><em>顯示控制台字體</em></p>`,30)),i("p",null,[n[4]||(n[4]=s("如果你的 Linux 發行版沒有 ",-1)),n[5]||(n[5]=i("code",null,"console-setup",-1)),n[6]||(n[6]=s("，你可以從",-1)),e(t,{href:"https://software.opensuse.org/package/console-setup"},{default:o(()=>[...n[3]||(n[3]=[s("這裏",-1)])]),_:1}),n[7]||(n[7]=s("獲取它。",-1))]),n[25]||(n[25]=p(`<p>在使用 Systemd 的 Linux 發行版上，你可以通過編輯 <code>/etc/vconsole.conf</code> 來更改控制台字體。</p><p>以下是德語鍵盤的示例配置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/vconsole.conf</span></span>
<span class="line"><span></span></span>
<span class="line"><span>KEYMAP=de-latin1</span></span>
<span class="line"><span>FONT=Lat2-Terminus16</span></span></code></pre></div><p>希望這篇文章對你有用！</p><hr>`,5)),i("p",null,[n[9]||(n[9]=s("via: ",-1)),e(t,{href:"https://www.ostechnix.com/how-to-change-linux-console-font-type-and-size/"},{default:o(()=>[...n[8]||(n[8]=[s("https://www.ostechnix.com/how-to-change-linux-console-font-type-and-size/",-1)])]),_:1})]),i("p",null,[n[14]||(n[14]=s("作者：",-1)),e(t,{href:"https://www.ostechnix.com/author/sk/"},{default:o(()=>[...n[10]||(n[10]=[s("sk",-1)])]),_:1}),n[15]||(n[15]=s(" 選題：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...n[11]||(n[11]=[s("lujun9972",-1)])]),_:1}),n[16]||(n[16]=s(" 譯者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:o(()=>[...n[12]||(n[12]=[s("geekpi",-1)])]),_:1}),n[17]||(n[17]=s(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:o(()=>[...n[13]||(n[13]=[s("wxy",-1)])]),_:1})]),i("p",null,[n[20]||(n[20]=s("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[18]||(n[18]=[s("LCTT",-1)])]),_:1}),n[21]||(n[21]=s(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:o(()=>[...n[19]||(n[19]=[s("Linux中國",-1)])]),_:1}),n[22]||(n[22]=s(" 榮譽推出",-1))])])}const k=a(r,[["render",g]]);export{b as __pageData,k as default};
